//! CLI alignment with the C SQLite 3.54.1 shell (step 5j). GENERATED by
//! target/perf-work/step5j/gen/gen_cli_tests.py from the differential situations of
//! target/perf-work/step5j/cli/cases.py: the expected standard output, standard error and exit code of
//! every case are those of the C shell for the same arguments, standard input and files.
#![forbid(unsafe_code)]

use std::io::Write;
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicU64, Ordering};

static SEQ: AtomicU64 = AtomicU64::new(1);

/// Runs the shell in a fresh directory and compares its output with the C shell's.
fn check(args: &[&str], stdin: &[u8], files: &[(&str, &[u8])], out: &[u8], err: &[u8], rc: i32) {
    let dir = std::env::temp_dir().join(format!(
        "sqliters-cli-5j-{}-{}",
        std::process::id(),
        SEQ.fetch_add(1, Ordering::Relaxed)
    ));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    for (name, data) in files {
        std::fs::write(dir.join(name), data).unwrap();
    }
    let bin = env!("CARGO_BIN_EXE_sqliters");
    let mut child = Command::new(bin)
        .args(args)
        .current_dir(&dir)
        .env_clear()
        .env("HOME", &dir)
        .env("PATH", "/usr/bin:/bin")
        .env("TERM", "dumb")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(stdin).unwrap();
    let res = child.wait_with_output().unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    // The program name appears in a few messages ("Usage: PROG ...").
    let norm = |b: &[u8]| String::from_utf8_lossy(b).replace(bin, "PROG");
    assert_eq!(norm(&res.stdout), String::from_utf8_lossy(out), "stdout");
    assert_eq!(norm(&res.stderr), String::from_utf8_lossy(err), "stderr");
    assert_eq!(res.status.code(), Some(rc), "exit code");
}

#[test]
fn optmode_csv_header_m1() {
    check(
        &["-csv", "-header", ":memory:"],
        b"create table t(id integer primary key, name, r, b, n);\ninsert into t values(1,'alpha beta',1.5,x'000141ff',NULL),(2,'it''s \"q\", x',1e100,x'',NULL),(3,'line1\nline2',-0.0,x'68656c6c6f',7),(4,'tab\there',123456789.125,zeroblob(2),0.1),(5,char(1,2,65,27,13,10,66),2.0,x'7b7d',1e15),(6,'\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e',9e999,jsonb('[1,2]'),-9e999),(7,'',0,x'0d0a',''),(8,' lead',5,x'41',' ');\nselect * from t;\nselect id from t where 0;\nselect 1 as 'a b', 2 as \"c,d\", NULL as n, 'x' as [e];\npragma auto_vacuum;\n",
        &[],
        b"id,name,r,b,n\r\n1,\"alpha beta\",1.5,^@^AA\xff,\r\n2,\"it's \"\"q\"\", x\",1.0e+100,,\r\n3,\"line1\nline2\",0.0,hello,7\r\n4,\"tab\there\",123456789.125,^@^@,0.1\r\n5,\"^A^BA^[\r\nB\",2.0,{},1000000000000000.0\r\n6,\"\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e\",Inf,K^S1^S2,-Inf\r\n7,\"\",0,\r\n,\"\"\r\n8,\" lead\",5,A,\" \"\r\nid\r\n\"a b\",\"c,d\",n,e\r\n1,2,,x\r\nauto_vacuum\r\n0\r\n",
        b"",
        0,
    );
}

