#[test]
fn dot_schema_indent_plain() {
    check(
        &[":memory:"],
        b"create table plain(a integer primary key, b text not null default 'x', c real, d blob, unique(b,c));\ncreate table \"odd name\"(\"col one\", [col two], `col three`);\ncreate table wr(k text primary key, v) without rowid;\ncreate table gen(a int, b int generated always as (a*2) virtual, c text as (a||'x') stored);\ncreate table ai(id integer primary key autoincrement, v);\ncreate index plain_c on plain(c);\ncreate unique index \"odd idx\" on \"odd name\"(\"col one\");\ncreate index plain_expr on plain(lower(b));\ncreate view v1 as select a, b from plain where a>1;\ncreate trigger tr1 after insert on plain begin\n  insert into ai(v) values(new.b);\n  update wr set v=v+1 where k='n';\nend;\ncreate trigger tr2 instead of insert on v1 begin select 1; end;\ncreate virtual table ft using fts5(body, title);\ncreate virtual table rt using rtree(id, x0, x1, y0, y1);\ninsert into plain values(1,'one',1.5,x'0102'),(2,'two',null,null),(3,'it''s',-0.0,x'');\ninsert into \"odd name\" values(1,'a b',null),('x',2.5,x'ff');\ninsert into wr values('n',1),('m','text'),('z',null);\ninsert into gen(a) values(1),(2),(null);\ninsert into ai(v) values('p'),('q');\ninsert into ft values('hello world','t1'),('second document here','t2');\ninsert into rt values(1,0,1,0,1),(2,5,6,5,6);\nanalyze;\n.schema --indent plain\n",
        &[],
        b"CREATE TABLE plain(\n  a integer primary key,\n  b text not null default 'x',\n  c real,\n  d blob,\n  unique(b,c)\n);\n\nCREATE INDEX plain_c on plain(c);\nCREATE INDEX plain_expr on plain(lower(b));\nCREATE TRIGGER tr1 after insert on plain begin\n  insert into ai(v) values(new.b);\n  update wr set v=v+1 where k='n';\nend;\n",
        b"",
        0,
    );
}

