#[test]
fn defensive_default() {
    check(
        &[":memory:"],
        b"create table t(a);\ncreate virtual table f using fts5(x);\ncreate virtual table r using rtree(id,x0,x1);\ninsert into f values('hello');\npragma journal_mode=off;\npragma journal_mode;\npragma schema_version=77;\npragma schema_version;\npragma writable_schema=on;\npragma writable_schema;\nupdate sqlite_schema set sql='create table t(a,b)' where name='t';\nselect sql from sqlite_schema where name='t';\ninsert into f_config values('zz',1);\ndelete from f_data;\ninsert into r_rowid values(99,1);\nupdate r_node set data=x'00' where nodeno=1;\ndrop table f_data;\nalter table f_data rename to zz;\nalter table f_data add column q;\ncreate index fx on f_data(id);\ncreate trigger ftr after insert on f_data begin select 1; end;\ncreate table sqlite_stat9(x);\ncreate table f_newshadow(x);\npragma journal_mode=memory;\npragma journal_mode=delete;\ndelete from sqlite_schema where name='t';\ninsert into sqlite_schema values('table','q','q',0,'create table q(a)');\nreplace into sqlite_schema values('table','q','q',0,'create table q(a)');\nselect count(*) from sqlite_schema;\ncreate table sqlite_sequence2(a);\nanalyze;\ndelete from sqlite_stat1;\ninsert into sqlite_stat1 values('t',null,'5');\ndrop table sqlite_stat1;\ncreate table ai(id integer primary key autoincrement);\ninsert into ai values(null);\nupdate sqlite_sequence set seq=100;\ndelete from sqlite_sequence;\ndrop table sqlite_sequence;\npragma writable_schema=reset;\npragma writable_schema;\npragma trusted_schema;\npragma cell_size_check;\nselect * from pragma_database_list;\nvacuum into 'v.db';\nselect count(*) from f_data;\nselect * from r_rowid;\npragma integrity_check;\n",
        &[],
        b"memory\nmemory\n11\n0\nCREATE TABLE t(a)\nmemory\nmemory\n13\n0\n0\n0\n0|main|\n3\nok\n",
        b"Parse error near line 11: table sqlite_master may not be modified\nParse error near line 13: table f_config may not be modified\nParse error near line 14: table f_data may not be modified\nParse error near line 15: table r_rowid may not be modified\nParse error near line 16: table r_node may not be modified\nParse error near line 17: table f_data may not be dropped\nParse error near line 18: table f_data may not be altered\nParse error near line 19: table f_data may not be altered\nParse error near line 21: cannot create triggers on shadow tables\nParse error near line 22: object name reserved for internal use: sqlite_stat9\nParse error near line 26: table sqlite_master may not be modified\nParse error near line 27: table sqlite_master may not be modified\nParse error near line 28: table sqlite_master may not be modified\nParse error near line 30: object name reserved for internal use: sqlite_sequence2\nParse error near line 39: table sqlite_sequence may not be dropped\n",
        1,
    );
}

